// Generated by ./gradlew generateIosResources from the shared design system's AppIcon.kt. Don't edit it:
// checkIosResources fails when it differs from what the Kotlin enum now produces.

/// The app's chrome icons, each as the SF Symbol the shared UI draws for it on iOS (dev/ios-native-resources).
enum AppIcon: CaseIterable {
    case back
    case search
    case add
    case record
    case manualEntry
    case `import`
    case settings
    case refresh
    case send
    case clear
    case calendar
    case check
    case chevron
    case chevronBack
    case chevronDown
    case chevronUp
    case delete
    case more
    case hide
    case unhide
    case ungroup
    case export
    case close
    case location
    case lock
    case addPhoto
    case dropDown
    case expandAll
    case collapseAll
    case expand
    case recenter
    case like
    case repost
    case quote
    case star
    case feed
    case you

    /// The icon's SF Symbol.
    var symbol: String {
        switch self {
        case .back: "chevron.backward"
        case .search: "magnifyingglass"
        case .add: "plus"
        case .record: "record.circle"
        case .manualEntry: "square.and.pencil"
        case .`import`: "tray.and.arrow.down"
        case .settings: "gearshape"
        case .refresh: "arrow.clockwise"
        case .send: "arrow.up.circle.fill"
        case .clear: "xmark.circle.fill"
        case .calendar: "calendar"
        case .check: "checkmark"
        case .chevron: "chevron.forward"
        case .chevronBack: "chevron.backward"
        case .chevronDown: "chevron.down"
        case .chevronUp: "chevron.up"
        case .delete: "trash"
        case .more: "ellipsis.circle"
        case .hide: "eye.slash"
        case .unhide: "eye"
        case .ungroup: "arrow.branch"
        case .export: "square.and.arrow.up"
        case .close: "xmark"
        case .location: "location"
        case .lock: "lock.fill"
        case .addPhoto: "photo.badge.plus"
        case .dropDown: "chevron.up.chevron.down"
        case .expandAll: "rectangle.expand.vertical"
        case .collapseAll: "rectangle.compress.vertical"
        case .expand: "arrow.up.left.and.arrow.down.right"
        case .recenter: "scope"
        case .like: "hand.thumbsup"
        case .repost: "arrow.2.squarepath"
        case .quote: "quote.bubble"
        case .star: "star"
        case .feed: "house"
        case .you: "person"
        }
    }

    /// The symbol of the icon's selected or active form, which is the plain one where it has no other.
    var filledSymbol: String {
        switch self {
        case .like: "hand.thumbsup.fill"
        case .star: "star.fill"
        case .feed: "house.fill"
        case .you: "person.fill"
        default: symbol
        }
    }
}
